import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useCallback } from 'react'
import { useProfileContextValue } from '../../../context'
import { PROFILE_ACTIONS } from '../actions'

export const useProfileServiceCall = (actionsCall = () => {}) => {
  const [myProfileState, dispatch] = useProfileContextValue()
  const [callApi] = useServiceRequest(dispatch)

  const request = useCallback((payload = {}) => {
    callApi(actionsCall({
      ...payload
    }))
  }, [callApi, actionsCall])
  return [myProfileState, request]
}

export const useUpdatePhoneNumber = () => {
  return useProfileServiceCall(PROFILE_ACTIONS.updatePhoneNumber)
}

export const useUpdateProfile = () => {
  return useProfileServiceCall(PROFILE_ACTIONS.updateProfile)
}

export const useUpdateAgentPhoneNo = () => {
  return useProfileServiceCall(PROFILE_ACTIONS.updateAgentPhoneNo)
}

export const useResendOtp = () => {
  return useProfileServiceCall(PROFILE_ACTIONS.resendOtp)
}
